1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	export type Damage = { itemType: string; amount: number };
8	export type Incident = { cause: string; damages: Damage[] };
9	
10	export type Step = {
11	  op: string;
12	  items?: Item[];
13	  policy?: number;
14	  incident?: Incident;
15	};
16	export type Customer = { yearsWithMHPCO: number };
17	export type Scenario = { customer: Customer; steps: Step[] };
18	
19	export type QuoteResult = { premium: number };
20	export type ClaimResult = { payout: number; remainingCap: number };
21	export type StepResult = QuoteResult | ClaimResult;
22	export type ScenarioResult = { results: StepResult[] };
23	
24	const BASE_PREMIUMS: Record<string, number> = {
25	  sword: 100,
26	  amulet: 60,
27	  staff: 80,
28	  potion: 40,
29	  rune: 25,
30	  moonstone: 25,
31	};
32	
33	const INSURANCE_VALUES: Record<string, number> = {
34	  sword: 1000,
35	  amulet: 600,
36	  staff: 800,
37	  potion: 400,
38	  rune: 250,
39	  moonstone: 250,
40	};
41	
42	const DEDUCTIBLE_PER_DAMAGE = 100;
43	const CAP_MULTIPLIER = 2;
44	const HALVED_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
45	const HALVED_REIMBURSEMENT_RATE = 0.5;
46	
47	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
48	const PROCESSING_FEE = 5;
49	
50	const CURSE_SURCHARGE_RATE = 0.5;
51	const SURCHARGED_ENCHANTMENT_LEVEL = 5;
52	const ENCHANTMENT_SURCHARGE_RATE = 0.3;
53	const LOYALTY_THRESHOLD_YEARS = 2;
54	const LOYALTY_DISCOUNT_RATE = 0.2;
55	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
56	
57	const BLOCK_SIZE = 3;
58	const BLOCK_BASE_PREMIUM = 60;
59	
60	const sum = (amounts: number[]): number =>
61	  amounts.reduce((total, amount) => total + amount, 0);
62	
63	const countByType = (items: Item[]): Map<string, number> => {
64	  const counts = new Map<string, number>();
65	  for (const item of items) {
66	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
67	  }
68	  return counts;
69	};
70	
71	// Exactly three alike components are priced as a discounted block; any other
72	// count, including four or more, is priced per item.
73	const basePremiumForAlikeItems = (type: string, count: number): number =>
74	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
75	
76	const policyBasePremium = (items: Item[]): number =>
77	  sum(
78	    [...countByType(items)].map(([type, count]) =>
79	      basePremiumForAlikeItems(type, count),
80	    ),
81	  );
82	
83	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
84	
85	// Only types the MHPCO publishes a price for can be insured. Checked up front
86	// so an unpriced type is reported by name, rather than silently making every
87	// downstream premium NaN.
88	const rejectUnpricedItems = (items: Item[]): void => {
89	  const unpriced = items.find((item) => !(item.type in BASE_PREMIUMS));
90	  if (unpriced) {
91	    throw new Error(`Unknown item type: ${unpriced.type}`);
92	  }
93	};
94	
95	const isCursed = (item: Item): boolean => item.cursed === true;
96	
97	const attractsEnchantmentSurcharge = (item: Item): boolean =>
98	  (item.enchantment ?? 0) >= SURCHARGED_ENCHANTMENT_LEVEL;
99	
100	const curseSurcharge = (item: Item): number =>
101	  isCursed(item) ? itemBasePremium(item) * CURSE_SURCHARGE_RATE : 0;
102	
103	const enchantmentSurcharge = (item: Item): number =>
104	  attractsEnchantmentSurcharge(item)
105	    ? itemBasePremium(item) * ENCHANTMENT_SURCHARGE_RATE
106	    : 0;
107	
108	const itemModifierSurcharges = (items: Item[]): number =>
109	  sum(items.map((item) => curseSurcharge(item) + enchantmentSurcharge(item)));
110	
111	const isLoyalCustomer = (customer: Customer): boolean =>
112	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
113	
114	// Policy-wide modifiers are rates applied to the policy base premium.
115	// Surcharges are positive, discounts negative; they sum to one net rate.
116	const policyModifierRates = (
117	  customer: Customer,
118	  isFollowUpContract: boolean,
119	): number[] => [
120	  FIRST_INSURANCE_SURCHARGE_RATE,
121	  isLoyalCustomer(customer) ? -LOYALTY_DISCOUNT_RATE : 0,
122	  isFollowUpContract ? -FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0,
123	];
124	
125	const netPolicyModifierRate = (
126	  customer: Customer,
127	  isFollowUpContract: boolean,
128	): number => sum(policyModifierRates(customer, isFollowUpContract));
129	
130	const quotePremium = (
131	  customer: Customer,
132	  items: Item[] = [],
133	  isFollowUpContract = false,
134	): number => {
135	  const policyBase = policyBasePremium(items);
136	  const policyModifiers =
137	    policyBase * netPolicyModifierRate(customer, isFollowUpContract);
138	  return Math.ceil(
139	    policyBase +
140	      itemModifierSurcharges(items) +
141	      policyModifiers +
142	      PROCESSING_FEE,
143	  );
144	};
145	
146	type Policy = { items: Item[]; remainingCap: number };
147	
148	const insuranceSum = (items: Item[]): number =>
149	  sum(items.map((item) => INSURANCE_VALUES[item.type]));
150	
151	const hasHalvedReimbursement = (item: Item): boolean =>
152	  (item.enchantment ?? 0) >= HALVED_REIMBURSEMENT_ENCHANTMENT_LEVEL;
153	
154	const reimbursedAmount = (item: Item, damage: Damage): number =>
155	  hasHalvedReimbursement(item)
156	    ? damage.amount * HALVED_REIMBURSEMENT_RATE
157	    : damage.amount;
158	
159	const damagePayout = (item: Item, damage: Damage): number =>
160	  reimbursedAmount(item, damage) - DEDUCTIBLE_PER_DAMAGE;
161	
162	type ClaimedItem = { item: Item; damage: Damage };
163	
164	// Removes and returns the first item of the wanted type. A damage with no
165	// item left to match is not covered — either the type was never insured, or
166	// every insured item of that type has already been claimed against in this
167	// same incident.
168	const claimAgainstItemOfType = (unclaimed: Item[], itemType: string): Item => {
169	  const matchIndex = unclaimed.findIndex((item) => item.type === itemType);
170	  if (matchIndex === -1) {
171	    throw new Error(
172	      `Damage reported for a ${itemType} that is not covered by this policy`,
173	    );
174	  }
175	  return unclaimed.splice(matchIndex, 1)[0];
176	};
177	
178	// A damage cannot be for less than nothing; a negative amount is a malformed
179	// report rather than a claim the MHPCO can settle.
180	const rejectNegativeDamages = (damages: Damage[]): void => {
181	  const negative = damages.find((damage) => damage.amount < 0);
182	  if (negative) {
183	    throw new Error(`Damage amount cannot be negative: ${negative.amount}`);
184	  }
185	};
186	
187	// Each damage entry is matched to a distinct insured item, so a policy
188	// covering two swords can absorb two separate sword damages but no more.
189	// Matching against a copy of the item list means each item is consumed at
190	// most once, and pairing the two up here keeps that correspondence in the
191	// data rather than leaving callers to line up two arrays by index.
192	const matchDamagesToItems = (
193	  policy: Policy,
194	  damages: Damage[],
195	): ClaimedItem[] => {
196	  const unclaimed = [...policy.items];
197	  return damages.map((damage) => ({
198	    item: claimAgainstItemOfType(unclaimed, damage.itemType),
199	    damage,
200	  }));
201	};
202	
203	// Payouts are summed as exact fractions and only then rounded down, so that
204	// rounding happens once per claim rather than once per damaged item.
205	const desiredPayout = (policy: Policy, incident: Incident): number =>
206	  Math.floor(
207	    sum(
208	      matchDamagesToItems(policy, incident.damages).map(({ item, damage }) =>
209	        damagePayout(item, damage),
210	      ),
211	    ),
212	  );
213	
214	const settleClaim = (policy: Policy, incident: Incident): ClaimResult => {
215	  rejectNegativeDamages(incident.damages);
216	  const payout = Math.min(desiredPayout(policy, incident), policy.remainingCap);
217	  policy.remainingCap -= payout;
218	  return { payout, remainingCap: policy.remainingCap };
219	};
220	
221	const openPolicy = (items: Item[]): Policy => ({
222	  items,
223	  remainingCap: insuranceSum(items) * CAP_MULTIPLIER,
224	});
225	
226	export const runScenario = (scenario: Scenario): ScenarioResult => {
227	  // Policies are keyed by the index of the quote step that opened them;
228	  // a claim step names that index in `step.policy`.
229	  const policies = new Map<number, Policy>();
230	
231	  const quoteStep = (step: Step, stepIndex: number): QuoteResult => {
232	    const items = step.items ?? [];
233	    rejectUnpricedItems(items);
234	    // A quote is a follow-up when some earlier step already opened a policy,
235	    // so this must be read before the new policy is registered below.
236	    const isFollowUpContract = policies.size > 0;
237	    policies.set(stepIndex, openPolicy(items));
238	    return {
239	      premium: quotePremium(scenario.customer, items, isFollowUpContract),
240	    };
241	  };
242	
243	  const claimStep = (step: Step): ClaimResult =>
244	    settleClaim(policies.get(step.policy ?? -1)!, step.incident!);
245	
246	  const results = scenario.steps.map((step, stepIndex): StepResult =>
247	    step.op === "claim" ? claimStep(step) : quoteStep(step, stepIndex),
248	  );
249	
250	  return { results };
251	};
