7	// stdin arrives in chunks of arbitrary size, so the whole scenario is
8	// collected before parsing rather than parsed incrementally.
9	const readAllStdin = async (): Promise<string> => {
10	  const chunks: Buffer[] = [];
11	  for await (const chunk of process.stdin) {
12	    chunks.push(chunk as Buffer);
13	  }
14	  return Buffer.concat(chunks).toString("utf8");
15	};
16	
17	const parseScenario = (input: string): Scenario => JSON.parse(input) as Scenario;
18	
19	const writeResults = (result: ScenarioResult): void => {
20	  process.stdout.write(JSON.stringify(result));
21	};
22	
23	const main = async (): Promise<void> => {
24	  writeResults(runScenario(parseScenario(await readAllStdin())));
25	};
26	
27	try {
28	  await main();
29	} catch (error) {
30	  // The MHPCO rejects the whole scenario: a description on stderr, nothing
31	  // on stdout, and a non-zero exit code.
32	  process.stderr.write(`${(error as Error).message}\n`);
33	  process.exit(1);
34	}
